    spectrum=new Spectrum(this);root.addView(spectrum,new LinearLayout.LayoutParams(-1,520));
    candidate=t("Candidate: —",18,true);root.addView(candidate);bankText=t("Auto Notches: 0 / 6",16,false);root.addView(bankText);
    Button undo=btn("UNDO LAST CUT"),restore=btn("RESTORE ORIGINAL EQ");root.addView(undo,lp());root.addView(restore,lp());log=t("Ready\nAUTO CUT is disarmed by default.",12,false);log.setTextColor(Color.LTGRAY);root.addView(log,lp());
    con.setOnClickListener(v->connect());undo.setOnClickListener(v->undo());restore.setOnClickListener(v->restore());
    target.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){if(sock!=null){bank.clear();configure();snapshot();refresh();}}public void onNothingSelected(android.widget.AdapterView<?> p){}});
